<?php
namespace App\Controllers; use App\Core\{Application,Response,Session}; use App\Repositories\ContentRepository; use App\Services\{CsrfService,ValidationService};
final class PublicController{private ContentRepository $repo; public function __construct(private Application $app){$this->repo=new ContentRepository($app);} private function base():array{return ['settings'=>$this->repo->settings(),'store'=>$this->repo->store(),'headerMenu'=>$this->repo->menu('header'),'footerMenu'=>$this->repo->menu('footer'),'csrf'=>CsrfService::token()];} public function home():string{return $this->app->view()->render('public/home',array_merge($this->base(),['sections'=>$this->repo->sections(),'collections'=>$this->repo->collections(true),'subcollections'=>$this->repo->subcollections(null,true),'products'=>$this->repo->products(true),'applications'=>$this->repo->applications(true)]));} public function collections():string{return $this->app->view()->render('public/collections',array_merge($this->base(),['collections'=>$this->repo->collections()]));} public function collection(string $slug):string{$c=$this->repo->collection($slug); if(!$c){Response::status(404);return $this->app->view()->render('errors/404',$this->base());} return $this->app->view()->render('public/collection',array_merge($this->base(),['collection'=>$c,'subcollections'=>$this->repo->subcollections((int)$c['id']),'products'=>$this->repo->products()]));} public function products():string{return $this->app->view()->render('public/products',array_merge($this->base(),['products'=>$this->repo->products()]));} public function product(string $slug):string{$p=$this->repo->product($slug); if(!$p){Response::status(404);return $this->app->view()->render('errors/404',$this->base());} return $this->app->view()->render('public/product',array_merge($this->base(),['product'=>$p,'images'=>$this->repo->productImages((int)$p['id']),'related'=>$this->repo->products(true)]));} public function applications():string{return $this->app->view()->render('public/applications',array_merge($this->base(),['applications'=>$this->repo->applications()]));} public function application(string $slug):string{$a=$this->repo->application($slug); if(!$a){Response::status(404);return $this->app->view()->render('errors/404',$this->base());} return $this->app->view()->render('public/application',array_merge($this->base(),['application'=>$a]));} public function store():string{return $this->app->view()->render('public/store',$this->base());} public function contact():string{return $this->app->view()->render('public/contact',array_merge($this->base(),['errors'=>[]]));} public function submitContact():string{if(!CsrfService::verify($_POST['_csrf']??null)){Response::status(419);return $this->app->view()->render('errors/419',$this->base());}$errors=(new ValidationService())->contact($_POST); if($errors)return $this->app->view()->render('public/contact',array_merge($this->base(),['errors'=>$errors,'old'=>$_POST])); $this->repo->saveContact($_POST); Session::flash('success','Talebiniz alındı. PERLINA ekibi kısa sürede dönüş yapacak.'); Response::redirect('/iletisim');} public function whatsapp():never{$msg=(string)($_GET['message']??'Merhaba, PERLINA hakkında bilgi almak istiyorum.');$this->repo->logWhatsapp((string)($_GET['context']??'general'),$msg);$phone=preg_replace('/\D+/','',$this->repo->store()['whatsapp']??'905551112233'); Response::redirect('https://wa.me/'.$phone.'?text='.rawurlencode($msg));}}
